// Builds the Assignment 1 report (.docx) from content.json (generated by content.py).
const fs = require("fs");
const path = require("path");
const {
  Document, Packer, Paragraph, TextRun, ImageRun, Table, TableRow, TableCell, WidthType,
  AlignmentType, HeadingLevel, ShadingType, BorderStyle, PageBreak, Footer, Header,
  PageNumber, LevelFormat, TableLayoutType,
} = require("docx");

const data = JSON.parse(fs.readFileSync(path.join(__dirname, "content.json"), "utf8"));
const PAGE_W = 11906, PAGE_H = 16838, MARGIN = 1200;            // A4, 0.83 in margins
const CONTENT_W = PAGE_W - 2 * MARGIN;                           // 9506 DXA
const FONT = "Arial", MONO = "Consolas";

// Parse **bold** segments into runs
function runs(text, opts = {}) {
  const parts = String(text).split(/(\*\*[^*]+\*\*)/g).filter(s => s.length);
  return parts.map(s => s.startsWith("**") && s.endsWith("**")
    ? new TextRun({ text: s.slice(2, -2), bold: true, font: FONT, size: opts.size || 22, color: opts.color })
    : new TextRun({ text: s, font: FONT, size: opts.size || 22, bold: opts.bold, color: opts.color, italics: opts.italics }));
}

const para = (text, o = {}) => new Paragraph({
  children: runs(text, o), alignment: o.align || AlignmentType.LEFT,
  spacing: { before: o.before ?? 60, after: o.after ?? 140, line: 300 }, keepNext: o.keepNext,
});

const heading = (text, level) => {
  const map = { 1: HeadingLevel.HEADING_1, 2: HeadingLevel.HEADING_2, 3: HeadingLevel.HEADING_3 };
  return new Paragraph({
    heading: map[level], keepNext: true, keepLines: true,
    children: [new TextRun({ text, font: FONT, bold: true, size: level === 1 ? 30 : level === 2 ? 25 : 23, color: level === 1 ? "1F3864" : "2E4A7A" })],
    spacing: { before: level === 1 ? 300 : 220, after: 120 },
    border: level === 1 ? { bottom: { style: BorderStyle.SINGLE, size: 8, color: "1F3864", space: 4 } } : undefined,
  });
};

const bullets = items => items.map(t => new Paragraph({
  numbering: { reference: "bul", level: 0 }, children: runs(t),
  spacing: { before: 40, after: 60, line: 290 }, alignment: AlignmentType.LEFT,
}));

const codeBlock = text => {
  const lines = text.split("\n");
  const border = { style: BorderStyle.SINGLE, size: 4, color: "BFBFBF" };
  return new Table({
    width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: [CONTENT_W],
    layout: TableLayoutType.FIXED,
    rows: [new TableRow({ children: [new TableCell({
      width: { size: CONTENT_W, type: WidthType.DXA },
      shading: { fill: "F4F6F8", type: ShadingType.CLEAR, color: "auto" },
      borders: { top: border, bottom: border, left: border, right: border },
      margins: { top: 100, bottom: 100, left: 160, right: 160 },
      children: lines.map(l => new Paragraph({
        spacing: { before: 0, after: 0, line: 240 }, keepNext: true, keepLines: true,
        children: [new TextRun({ text: l.length ? l : " ", font: MONO, size: 17 })],
      })),
    })] })],
  });
};

const cell = (text, w, head) => new TableCell({
  width: { size: w, type: WidthType.DXA },
  shading: head ? { fill: "1F3864", type: ShadingType.CLEAR, color: "auto" } : undefined,
  margins: { top: 70, bottom: 70, left: 100, right: 100 },
  children: [new Paragraph({
    alignment: AlignmentType.LEFT, spacing: { before: 0, after: 0, line: 260 },
    children: runs(String(text), { size: 18, bold: head, color: head ? "FFFFFF" : undefined }),
  })],
});

const tableBlock = (head, rows, fr) => {
  const sum = fr.reduce((a, b) => a + b, 0);
  let widths = fr.map(f => Math.round(f / sum * CONTENT_W));
  widths[widths.length - 1] += CONTENT_W - widths.reduce((a, b) => a + b, 0);
  const border = { style: BorderStyle.SINGLE, size: 4, color: "8C9BB0" };
  const borders = { top: border, bottom: border, left: border, right: border };
  return new Table({
    width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: widths, layout: TableLayoutType.FIXED,
    rows: [
      new TableRow({ tableHeader: true, children: head.map((h, i) => new TableCell({ ...cellProps(widths[i], borders, true), children: cell(h, widths[i], true).options.children })) }),
      ...rows.map((r, ri) => new TableRow({ cantSplit: true, children: r.map((c, i) => new TableCell({ ...cellProps(widths[i], borders, false, ri), children: cell(c, widths[i], false).options.children })) })),
    ],
  });
};
function cellProps(w, borders, head, ri) {
  return {
    width: { size: w, type: WidthType.DXA }, borders,
    shading: head ? { fill: "1F3864", type: ShadingType.CLEAR, color: "auto" }
      : (ri % 2 ? { fill: "F2F6FB", type: ShadingType.CLEAR, color: "auto" } : undefined),
    margins: { top: 70, bottom: 70, left: 100, right: 100 },
  };
}

const caption = text => new Paragraph({
  children: runs(text, { size: 18, italics: true, color: "404040" }), alignment: AlignmentType.CENTER,
  spacing: { before: 80, after: 220 },
});

function image(b) {
  const [pw, ph] = b.px;
  const wpx = Math.round(b.w_in * 96), hpx = Math.round(wpx * ph / pw);
  return [
    new Paragraph({ alignment: AlignmentType.CENTER, keepNext: true, spacing: { before: 160, after: 60 },
      children: [new ImageRun({ type: "png", data: fs.readFileSync(b.src), transformation: { width: wpx, height: hpx },
        altText: { title: b.caption, description: b.caption, name: path.basename(b.src) } })] }),
    caption(b.caption),
  ];
}

function cover() {
  const out = [new Paragraph({ spacing: { before: 900 } })];
  for (const [text, size, bold] of data.cover.lines) {
    out.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 60, after: 60 },
      children: [new TextRun({ text, font: FONT, size, bold, color: "1F3864" })] }));
  }
  out.push(new Paragraph({ spacing: { before: 500 } }));
  const fr = data.cover.fields;
  out.push(new Table({
    width: { size: 7000, type: WidthType.DXA }, columnWidths: [2600, 4400], layout: TableLayoutType.FIXED,
    alignment: AlignmentType.CENTER,
    rows: fr.map(([k, v]) => new TableRow({ children: [
      new TableCell({ width: { size: 2600, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 80, right: 80 },
        children: [new Paragraph({ children: [new TextRun({ text: k, font: FONT, size: 22, bold: true })] })] }),
      new TableCell({ width: { size: 4400, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 80, right: 80 },
        children: [new Paragraph({ children: [new TextRun({ text: v, font: FONT, size: 22 })] })] }),
    ] })),
  }));
  return out;
}

const children = [];
for (const b of data.blocks) {
  switch (b.t) {
    case "cover": children.push(...cover()); break;
    case "h1": children.push(heading(b.x, 1)); break;
    case "h2": children.push(heading(b.x, 2)); break;
    case "h3": children.push(heading(b.x, 3)); break;
    case "p": children.push(para(b.x)); break;
    case "bul": children.push(...bullets(b.items)); break;
    case "code": children.push(codeBlock(b.x), new Paragraph({ spacing: { before: 0, after: 120 } })); break;
    case "table": children.push(tableBlock(b.head, b.rows, b.w), caption(b.caption)); break;
    case "img": children.push(...image(b)); break;
    case "pb": children.push(new Paragraph({ children: [new PageBreak()] })); break;
  }
}

const doc = new Document({
  creator: "CSA06 Assignment 1", title: "Assignment 1 CO1 – Search Strategies Report",
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { font: FONT, size: 30, bold: true, color: "1F3864" }, paragraph: { spacing: { before: 300, after: 120 }, keepNext: true, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { font: FONT, size: 25, bold: true, color: "2E4A7A" }, paragraph: { spacing: { before: 220, after: 120 }, keepNext: true, outlineLevel: 1 } },
      { id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true, run: { font: FONT, size: 23, bold: true, color: "2E4A7A" }, paragraph: { spacing: { before: 200, after: 100 }, keepNext: true, outlineLevel: 2 } },
    ],
  },
  numbering: { config: [{ reference: "bul", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT,
    style: { paragraph: { indent: { left: 540, hanging: 270 } } } }] }] },
  sections: [{
    properties: { page: { size: { width: PAGE_W, height: PAGE_H }, margin: { top: MARGIN, bottom: MARGIN, left: MARGIN, right: MARGIN } } },
    headers: { default: new Header({ children: [new Paragraph({ alignment: AlignmentType.RIGHT,
      children: [new TextRun({ text: "CSA06 · Assignment 1 (CO1) · Search Strategies", font: FONT, size: 16, color: "7F7F7F" })] })] }) },
    footers: { default: new Footer({ children: [new Paragraph({ alignment: AlignmentType.CENTER,
      children: [new TextRun({ children: ["Page ", PageNumber.CURRENT, " of ", PageNumber.TOTAL_PAGES], font: FONT, size: 16, color: "7F7F7F" })] })] }) },
    children,
  }],
});

const out = process.argv[2] || path.join(__dirname, "CO1_Assignment_1_Search_Strategies_Report.docx");
Packer.toBuffer(doc).then(buf => { fs.writeFileSync(out, buf); console.log("wrote", out, buf.length, "bytes"); });
